//import {Oscilloscope} from "https://unpkg.com/webaudio-oscilloscope@3.2.1/dist/index.js";


let {Oscilloscope} = _osc

let outputNode;
let device;
let context;
let radio_div;
let date_div = document.getElementById("date");

let radio_stations = {
	217751405: { title: "ARCY Radio", author: "Rabiha Chowdhury" },
	218860916: { title: "Blade Runner FM", author: "Luca Iamundo" },
	219600360: { title: "Chaos and tingles", author: "Tsz Him Ng" },
	218856542: {
	  title: "Clockwork performance from the robot band, Power Chord!",
	  author: "Robert Jamrocha-Tullo"
	},
	219678788: { title: "Domo Arigato Mr. Roboto", author: "Seila Bak" },
	216416901: { title: "HiFi MeLo", author: "Ul Abdin Zain-Ul-Abdin" },
	217898909: { title: "Morrowind: FM", author: "Hassan El-Gazzar" },
	220007787: { title: "Mysterious Tension", author: "Jin Yong Maeng" },
	219719616: { title: "Outside", author: "Emma Su" },
	218836585: { title: "Radio Insanity", author: "Arsalan Khan" },
	217277237: { title: "The Two-Toned Conversation", author: "Emile Hosein" },
	220016416: {
	  title: "水琴窟　すいきんくつ Suikinkutsu",
	  author: "Hiromune Kubayashi"
	}
};

let scope = document.getElementById("scope")
let resize = function () {
	scope.width = window.innerWidth * 0.6;
	scope.height = scope.width/6;
};
window.addEventListener("resize", resize);
resize();

function setup() {
	for (let [id, station] of Object.entries(radio_stations)) {
		station.freq = 87.5 + Number(id.split("").reverse().slice(0,4).join(""))/10000 * (108-87.5)
	}

	let stations = Object.values(radio_stations).sort((a,b)=>a.freq - b.freq)
	for (let station of stations) {
		let div = document.createElement("button");
		div.innerText = station.freq.toFixed(2);
		document.getElementById("channels").appendChild(div);
		div.onclick = (event) => {
			radio_div = div;
			//console.log("start radio", radio_div.id);
			playStation(station);
		};
	}
}
setup();

// Clock parameters:
setInterval(() => {
	let currentdate = new Date();
	if (date_div && device) {
		date_div.innerText =
		currentdate.getDate() +
		"/" +
		(currentdate.getMonth() + 1) +
		"/" +
		currentdate.getFullYear() +
		" " +
		currentdate.getHours() +
		":" +
		currentdate.getMinutes().toString().padStart(2, "0") +
		":" +
		currentdate.getSeconds().toString().padStart(2, "0");
	}
  
	if (device) {
	  device.parameters.forEach((param) => {
		switch (param.name) {
		  case "CLOCK_RADIO/second": {
			param.value = currentdate.getSeconds();
			break;
		  }
		  case "CLOCK_RADIO/minute": {
			param.value = currentdate.getMinutes();
			break;
		  }
		  case "CLOCK_RADIO/hour": {
			param.value = currentdate.getHours();
			break;
		  }
		  case "CLOCK_RADIO/day": {
			param.value = currentdate.getDate();
			break;
		  }
		  case "CLOCK_RADIO/month": {
			param.value = currentdate.getMonth();
			break;
		  }
		}
	  });
	}
  }, 1000);
  
  async function playStation(station) {
	let { title, author, patcher } = station
	if (!outputNode) {
	  // Create AudioContext
	  const WAContext = window.AudioContext || window.webkitAudioContext;
	  context = new WAContext();
	  //console.log("created context");
  
	  // Create gain node and connect it to audio output
	  outputNode = context.createGain();
	  outputNode.connect(context.destination);
	}

	let osc = new Oscilloscope(context, outputNode, scope, null, 2048, null, (ctx, width, height)=>{
		ctx.fillStyle   = "#000";
		ctx.strokeStyle = "#fff";
	});
	osc.start();
  
	// remove any current device:
	if (device != null) {
	  device.node.disconnect(outputNode);
	}
	if (radio_div != null) {
	  // remove any activated styling on it
	}
  
	// load RNBO
	if (!window.RNBO) {
	  // Load RNBO script dynamically
	  // Note that you can skip this by knowing the RNBO version of your patch
	  // beforehand and just include it using a <script> tag
	  await loadRNBOScript(patcher.desc.meta.rnboversion);
	  //console.log("loaded RNBO");
	}
  
	// Create the device
	try {
	  device = await RNBO.createDevice({ context, patcher });
	} catch (err) {
	  if (typeof guardrails === "function") {
		guardrails({ error: err });
	  } else {
		throw err;
	  }
	  return;
	}
	//console.log("created device");
  
	// Connect the device to the web audio graph
	device.node.connect(outputNode);
	//console.log("connected device");
	context.resume();

	document.getElementById("title").innerText = station.title
	document.getElementById("author").innerText = station.author
  
  }
  
  function loadRNBOScript(version) {
	return new Promise((resolve, reject) => {
	  if (/^\d+\.\d+\.\d+-dev$/.test(version)) {
		throw new Error(
		  "Patcher exported with a Debug Version!\nPlease specify the correct RNBO version to use in the code."
		);
	  }
	  const el = document.createElement("script");
	  el.src =
		"https://c74-public.nyc3.digitaloceanspaces.com/rnbo/" +
		encodeURIComponent(version) +
		"/rnbo.min.js";
	  el.onload = resolve;
	  el.onerror = function (err) {
		console.log(err);
		reject(new Error("Failed to load rnbo.js v" + version));
	  };
	  document.body.append(el);
	});
  }
  
